"""Dry-run by default: reclaim expired private staging/export objects, never catalogue assets."""
import argparse
from datetime import datetime, timedelta, timezone
import re

import httpx
from fastapi import HTTPException

from app.core.config import Settings
from app.modules.functional.resources.direct_uploads import cloud


def purge(settings, client, *, execute=False, now=None, limit=100):
    origin, bucket, headers = cloud(settings)
    cutoff = (now or datetime.now(timezone.utc)) - timedelta(hours=24)
    candidates = []
    # Names are generated by direct_uploads only. The retention window exceeds
    # both the two-hour upload authorization and five-minute export URL lifetime.
    for prefix, pattern in (('staged-uploads', r'[0-9a-f]{32}'),
                            ('transfer-exports', r'[0-9a-f]{32}\.(xlsx|zip)')):
        offset = 0
        while len(candidates) < limit and offset < 10000:
            response = client.post(origin + '/object/list/' + bucket, headers=headers,
                json={'prefix': prefix, 'limit': 100, 'offset': offset,
                      'sortBy': {'column': 'created_at', 'order': 'asc'}})
            if response.status_code != 200:
                raise RuntimeError('Transfer inventory unavailable')
            rows = response.json()
            if not isinstance(rows, list):
                raise RuntimeError('Invalid transfer inventory')
            for row in rows:
                if not isinstance(row, dict) or not row.get('id') or not re.fullmatch(pattern, str(row.get('name', ''))):
                    continue
                try:
                    created = datetime.fromisoformat(row['created_at'].replace('Z', '+00:00'))
                    updated = datetime.fromisoformat(row['updated_at'].replace('Z', '+00:00'))
                except (KeyError, ValueError, TypeError, AttributeError):
                    continue
                if created.tzinfo and updated.tzinfo and max(created, updated) < cutoff:
                    candidates.append(prefix + '/' + row['name'])
                    if len(candidates) == limit:
                        break
            if len(rows) < 100:
                break
            offset += len(rows)
    if execute and candidates:
        response = client.request('DELETE', origin + '/object/' + bucket, headers=headers,
                                  json={'prefixes': candidates})
        if response.status_code != 200:
            raise RuntimeError('Transfer cleanup unconfirmed')
    return {'expired_candidates': len(candidates), 'removed': len(candidates) if execute else 0,
            'dry_run': not execute}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--execute', action='store_true')
    parser.add_argument('--limit', type=int, default=100)
    args = parser.parse_args()
    if not 1 <= args.limit <= 1000:
        parser.error('--limit must be between 1 and 1000')
    try:
        with httpx.Client(timeout=20, follow_redirects=False) as client:
            print(purge(Settings(), client, execute=args.execute, limit=args.limit))
    except (RuntimeError, httpx.HTTPError, ValueError, HTTPException):
        raise SystemExit('Private transfer cleanup failed; no credentials or object URLs are logged.')


if __name__ == '__main__':
    main()
